input.schema:
{
  "type": "record",
  "name": "Envelope",
  "namespace": "axt",
  "doc": "One AXT message. Defined in spec/envelope.md. The field order is part of the format: format is always the first field, signature always the last.",
  "fields": [
    {
      "name": "format",
      "type": "int",
      "doc": "Version of the envelope format. 1 for the envelope defined in spec/envelope.md. Every later envelope schema keeps this field first and of type int."
    },
    {
      "name": "kind",
      "type": {
        "type": "enum",
        "name": "Kind",
        "doc": "What the message is. Each kind is defined in the document named in spec/envelope.md, section 2.2. DEVICE_JOIN, DEVICE_ADD and DEVICE_REMOVE: the devices of one sender, spec/keys.md, section 5. CHANGE and RESYNC: records between the devices of one sender, to come with axt-1024. FORWARD: a message of another app passed on between the devices of one sender, to come with axt-1025. WITHDRAW: a record its sender no longer shares, to come with axt-1026. PROPOSAL and PROPOSAL_REPLY: a change a receiver proposes to a record's sender, and the answer, to come with axt-1027.",
        "symbols": [
          "MANIFEST",
          "OFFER",
          "ACCEPT",
          "DECLINE",
          "DATA",
          "DELETE",
          "ACK",
          "ERROR",
          "DEVICE_JOIN",
          "DEVICE_ADD",
          "DEVICE_REMOVE",
          "CHANGE",
          "RESYNC",
          "FORWARD",
          "WITHDRAW",
          "PROPOSAL",
          "PROPOSAL_REPLY"
        ]
      },
      "doc": "What the message is, and so which schema its body has."
    },
    {
      "name": "sender",
      "type": {
        "type": "fixed",
        "name": "PublicKey",
        "size": 32,
        "doc": "An Ed25519 public key in the encoding of RFC 8032. Defined in spec/keys.md."
      },
      "doc": "The Ed25519 public key of the sending device, which made the signature."
    },
    {
      "name": "record",
      "type": [
        "null",
        {
          "type": "record",
          "name": "RecordRef",
          "doc": "Which record, and which version of it, a message is about. Defined in spec/records.md.",
          "fields": [
            {
              "name": "id",
              "type": {
                "type": "string",
                "logicalType": "uuid"
              },
              "doc": "The record's stable id, a UUID in its 36-character lower-case text form."
            },
            {
              "name": "version",
              "type": "long",
              "doc": "The record's version. Defined in spec/records.md."
            }
          ]
        }
      ],
      "default": null,
      "doc": "The record the message is about; null for messages that are not about one record."
    },
    {
      "name": "body",
      "type": "bytes",
      "doc": "Empty, or one datum in Avro single-object encoding: the marker C3 01, the 8-byte little-endian CRC-64-AVRO fingerprint of the datum's writer schema, then the datum in Avro binary encoding."
    },
    {
      "name": "signature",
      "type": {
        "type": "fixed",
        "name": "Signature",
        "size": 64,
        "doc": "An Ed25519 signature. Defined in spec/keys.md."
      },
      "doc": "The sender's signature over the message. What it covers is defined in spec/keys.md."
    }
  ]
}

{
  "type": "record",
  "name": "Manifest",
  "namespace": "axt",
  "doc": "The types an app takes and what it does with them; the body of a MANIFEST message. Defined in spec/manifest.md. Its schema changes only with a new envelope format.",
  "fields": [
    {
      "name": "revision",
      "type": "long",
      "doc": "The revision of this manifest, at least 1. It rises with every change of the manifest's content, so that a receiver can tell the latest of several manifests of the same app apart from older ones."
    },
    {
      "name": "app_name",
      "type": "string",
      "doc": "The name the app gives itself, as plain text on one line, such as Old Brain Fix. It is shown to the other app's user; it does not identify the app, the keys of its sender do, of which the sender key of the envelope is one."
    },
    {
      "name": "app_url",
      "type": [
        "null",
        "string"
      ],
      "default": null,
      "doc": "An absolute https URL of a page about the app. Null when the app names none."
    },
    {
      "name": "formats",
      "type": {
        "type": "array",
        "items": "int"
      },
      "doc": "The envelope formats the app reads, each at least 1, without duplicates. It includes the format of the envelope that carries this manifest."
    },
    {
      "name": "takes",
      "type": {
        "type": "array",
        "items": {
          "type": "record",
          "name": "ManifestTake",
          "doc": "One type the app takes, the versions of it it takes, and what it does with its records.",
          "fields": [
            {
              "name": "type",
              "type": "string",
              "doc": "The full name of the type, namespace and name, such as axt.example.v1.Appointment. Matched exactly; the major version is part of the name."
            },
            {
              "name": "min_version",
              "type": "int",
              "doc": "The lowest version of the type the app takes, as the type's axt.version attribute numbers it; at least 1. A schema without a valid axt.version counts as version 1."
            },
            {
              "name": "max_version",
              "type": [
                "null",
                "int"
              ],
              "default": null,
              "doc": "The highest version of the type the app takes, at least min_version. Null when the app takes every version from min_version on."
            },
            {
              "name": "purpose",
              "type": "string",
              "doc": "One sentence in English, plain text on one line, on what the app does with records of the type, such as: An Appointment becomes a Reminder."
            },
            {
              "name": "purpose_translations",
              "type": {
                "type": "map",
                "values": "string"
              },
              "default": {},
              "doc": "The sentence of the field purpose in other languages. Each key is a BCP 47 language tag other than en, such as de or pt-BR; each value is the sentence in that language, plain text on one line. Empty when there are none."
            }
          ]
        }
      },
      "default": [],
      "doc": "The types the app takes, each full name at most once. Empty when the app takes no type by name."
    },
    {
      "name": "any_type",
      "type": [
        "null",
        {
          "type": "record",
          "name": "ManifestAnyType",
          "doc": "That the app takes every type that takes does not name, in every version, and what it does with their records.",
          "fields": [
            {
              "name": "purpose",
              "type": "string",
              "doc": "One sentence in English, plain text on one line, on what the app does with records of a type that takes does not name, such as: Any other type becomes a searchable Note."
            },
            {
              "name": "purpose_translations",
              "type": {
                "type": "map",
                "values": "string"
              },
              "default": {},
              "doc": "The sentence of the field purpose in other languages, keyed by BCP 47 language tag other than en, as in ManifestTake. Empty when there are none."
            }
          ]
        }
      ],
      "default": null,
      "doc": "Whether the app takes every type that takes does not name. Null when it takes only the types in takes."
    },
    {
      "name": "sends",
      "type": [
        "null",
        {
          "type": "array",
          "items": {
            "type": "record",
            "name": "ManifestSend",
            "doc": "One type the app may send, the versions of it it writes, and whether it takes proposals for its records of the type.",
            "fields": [
              {
                "name": "type",
                "type": "string",
                "doc": "The full name of the type, namespace and name, such as axt.example.v1.Pet."
              },
              {
                "name": "min_version",
                "type": "int",
                "doc": "The lowest version of the type the app writes, as the type's axt.version attribute numbers it; at least 1. A schema without a valid axt.version counts as version 1."
              },
              {
                "name": "max_version",
                "type": [
                  "null",
                  "int"
                ],
                "default": null,
                "doc": "The highest version of the type the app writes, at least min_version. Null when the app does not say."
              },
              {
                "name": "proposals",
                "type": "boolean",
                "default": false,
                "doc": "Whether the app takes proposals of changes to the records of this type it sends, as PROPOSAL messages, to come with axt-1027. False when it takes none."
              }
            ]
          }
        }
      ],
      "default": null,
      "doc": "The types the app may send, each full name at most once; for display only. Null when the app does not say; empty when it sends no type."
    },
    {
      "name": "encryption_key",
      "type": [
        "null",
        {
          "type": "fixed",
          "name": "ManifestEncryptionKey",
          "size": 32,
          "doc": "An X25519 public key in the encoding of RFC 7748. Defined in spec/keys.md."
        }
      ],
      "default": null,
      "doc": "The X25519 public key of this installation with which other apps encrypt messages to it through a relay, as spec/keys.md defines. Null when the app takes no messages through a relay."
    },
    {
      "name": "relay",
      "type": [
        "null",
        {
          "type": "record",
          "name": "ManifestRelay",
          "doc": "The relay and the mailbox at it into which other apps put messages for this installation. Defined in spec/transports.md.",
          "fields": [
            {
              "name": "url",
              "type": "string",
              "doc": "The base URL of the relay: an absolute https URL with a host, ending with a slash, without user information, query or fragment, at most 256 bytes, such as https://relay.example.org/axt/. The paths of the relay's interface are appended to it."
            },
            {
              "name": "mailbox",
              "type": {
                "type": "fixed",
                "name": "ManifestRelayMailbox",
                "size": 32,
                "doc": "A mailbox id: the SHA-256 of a fixed prefix and the mailbox secret that only the mailbox's owner holds. Defined in spec/transports.md."
              },
              "doc": "The id of the mailbox at the relay into which other apps put messages for this installation."
            }
          ]
        }
      ],
      "default": null,
      "doc": "Where other apps put messages for this installation through a relay. Null when the app takes no messages through a relay; it is present exactly when encryption_key is."
    }
  ]
}

{
  "type": "record",
  "name": "DeviceJoin",
  "namespace": "axt",
  "doc": "The body of a DEVICE_JOIN message: a new device asks a device of its owner, whose join code it scanned, to add its key to the devices of that device's sender. Defined in spec/keys.md, section 5.2. The message is signed with the new device's key, which is its sender. It travels only in the live connection the join code opened. Its schema changes only with a new envelope format.",
  "fields": [
    {
      "name": "to",
      "type": {
        "type": "fixed",
        "name": "DeviceJoinTo",
        "size": 32,
        "doc": "An Ed25519 public key in the encoding of RFC 8032. Defined in spec/keys.md."
      },
      "doc": "The Ed25519 public key of the device that showed the join code, which is asked to add the new device. A device ignores a DEVICE_JOIN that names another key."
    },
    {
      "name": "proof",
      "type": {
        "type": "fixed",
        "name": "DeviceJoinProof",
        "size": 64,
        "doc": "An Ed25519 signature. Defined in spec/keys.md."
      },
      "doc": "The signature of the new device's key over the key in to and the new device's key, as spec/keys.md, section 5.2, defines; the device that adds the new device puts it into its DEVICE_ADD."
    }
  ]
}

{
  "type": "record",
  "name": "DeviceAdd",
  "namespace": "axt",
  "doc": "The body of a DEVICE_ADD message: a device adds the key of a new device to the devices of its sender. Defined in spec/keys.md, section 5.2. The message is signed with the key of a device that is already one of the sender's, which is its sender. Its schema changes only with a new envelope format.",
  "fields": [
    {
      "name": "device",
      "type": {
        "type": "fixed",
        "name": "DeviceAddDevice",
        "size": 32,
        "doc": "An Ed25519 public key in the encoding of RFC 8032. Defined in spec/keys.md."
      },
      "doc": "The Ed25519 public key of the new device, which from then on signs messages of the same sender."
    },
    {
      "name": "proof",
      "type": {
        "type": "fixed",
        "name": "DeviceAddProof",
        "size": 64,
        "doc": "An Ed25519 signature. Defined in spec/keys.md."
      },
      "doc": "The signature of the new device's key over the key of the message's sender and the new device's key, as spec/keys.md, section 5.2, defines; it shows that the new device holds its key and joins this sender."
    }
  ]
}

{
  "type": "record",
  "name": "DeviceRemove",
  "namespace": "axt",
  "doc": "The body of a DEVICE_REMOVE message: a device removes the key of another device from the devices of its sender. Defined in spec/keys.md, section 5.3. The message is signed with the key of a device of the sender, which is its sender and is never the removed device itself. Its schema changes only with a new envelope format.",
  "fields": [
    {
      "name": "device",
      "type": {
        "type": "fixed",
        "name": "DeviceRemoveDevice",
        "size": 32,
        "doc": "An Ed25519 public key in the encoding of RFC 8032. Defined in spec/keys.md."
      },
      "doc": "The Ed25519 public key of the removed device, another key than the message's sender. Receivers reject every later message signed with it, and it is never added to the sender again."
    }
  ]
}

{
  "type": "record",
  "name": "Offer",
  "namespace": "axt",
  "doc": "The body of an OFFER message: the types, each with its writer schema, whose records the sender wants to send to one receiver. Defined in spec/protocol.md. Its schema changes only with a new envelope format.",
  "fields": [
    {
      "name": "to",
      "type": {
        "type": "fixed",
        "name": "OfferTo",
        "size": 32,
        "doc": "An Ed25519 public key in the encoding of RFC 8032. Defined in spec/keys.md."
      },
      "doc": "The Ed25519 public key of the device the offer is made to, a current key of the receiver. A device ignores an offer that names another key."
    },
    {
      "name": "offer_id",
      "type": {
        "type": "string",
        "logicalType": "uuid"
      },
      "doc": "The id of the offer, a version 4 or 7 UUID in its 36-character lower-case text form, which the sender never uses for another offer. The answers to the offer name it."
    },
    {
      "name": "types",
      "type": {
        "type": "array",
        "items": {
          "type": "record",
          "name": "OfferType",
          "doc": "One type the sender offers, with the writer schema of its records.",
          "fields": [
            {
              "name": "schema",
              "type": "string",
              "doc": "The writer schema of the type as its full JSON text, doc attributes and axt.version included, with which the sender writes the records it sends under this offer. The type's full name and version are those of this schema."
            },
            {
              "name": "count",
              "type": "long",
              "default": 0,
              "doc": "The number of record messages of the type, DATA and DELETE together, that the sender is about to send under this offer; for display only. 0 when the sender does not say."
            }
          ]
        }
      },
      "doc": "The types offered, 1 to 256, each full name and each fingerprint at most once."
    }
  ]
}

{
  "type": "record",
  "name": "Accept",
  "namespace": "axt",
  "doc": "The body of an ACCEPT message: the types of one offer that the receiver takes. Defined in spec/protocol.md. Its schema changes only with a new envelope format.",
  "fields": [
    {
      "name": "to",
      "type": {
        "type": "fixed",
        "name": "AcceptTo",
        "size": 32,
        "doc": "An Ed25519 public key in the encoding of RFC 8032. Defined in spec/keys.md."
      },
      "doc": "The Ed25519 public key that signed the offer, the key of one device of its sender. A device ignores an answer that names another key."
    },
    {
      "name": "offer_id",
      "type": {
        "type": "string",
        "logicalType": "uuid"
      },
      "doc": "The id of the offer this message answers."
    },
    {
      "name": "types",
      "type": {
        "type": "array",
        "items": "string"
      },
      "doc": "The full names of the offered types the receiver takes, 1 to 256, each a type of the offer and each at most once."
    }
  ]
}

{
  "type": "record",
  "name": "Decline",
  "namespace": "axt",
  "doc": "The body of a DECLINE message: the types of one offer that the receiver does not take, each with the reason. Defined in spec/protocol.md. Its schema changes only with a new envelope format.",
  "fields": [
    {
      "name": "to",
      "type": {
        "type": "fixed",
        "name": "DeclineTo",
        "size": 32,
        "doc": "An Ed25519 public key in the encoding of RFC 8032. Defined in spec/keys.md."
      },
      "doc": "The Ed25519 public key that signed the offer, the key of one device of its sender. A device ignores an answer that names another key."
    },
    {
      "name": "offer_id",
      "type": {
        "type": "string",
        "logicalType": "uuid"
      },
      "doc": "The id of the offer this message answers."
    },
    {
      "name": "types",
      "type": {
        "type": "array",
        "items": {
          "type": "record",
          "name": "DeclineType",
          "doc": "One offered type the receiver does not take.",
          "fields": [
            {
              "name": "type",
              "type": "string",
              "doc": "The full name of the offered type."
            },
            {
              "name": "reason",
              "type": {
                "type": "enum",
                "name": "DeclineReason",
                "doc": "Why the receiver does not take a type. NOT_WANTED: the receiver or its user chose not to take it. DOES_NOT_FIT: the type, in the offered version, does not fit the receiver's current manifest. DOES_NOT_RESOLVE: the offered schema does not resolve against the receiver's reader schema of the type. The default is for schema resolution only; within one envelope format every symbol is known.",
                "symbols": [
                  "NOT_WANTED",
                  "DOES_NOT_FIT",
                  "DOES_NOT_RESOLVE"
                ],
                "default": "NOT_WANTED"
              },
              "doc": "Why the receiver does not take the type."
            }
          ]
        }
      },
      "doc": "The offered types the receiver does not take, 1 to 256, each a type of the offer and each at most once."
    }
  ]
}

{
  "type": "record",
  "name": "Ack",
  "namespace": "axt",
  "doc": "The body of an ACK message: what the receiver did with record messages of the device it sends the acknowledgement to. Defined in spec/protocol.md. Its schema changes only with a new envelope format.",
  "fields": [
    {
      "name": "to",
      "type": {
        "type": "fixed",
        "name": "AckTo",
        "size": 32,
        "doc": "An Ed25519 public key in the encoding of RFC 8032. Defined in spec/keys.md."
      },
      "doc": "The Ed25519 public key that signed the acknowledged record messages, the key of one device of their sender. A device ignores an acknowledgement that names another key."
    },
    {
      "name": "records",
      "type": {
        "type": "array",
        "items": {
          "type": "record",
          "name": "AckRecord",
          "doc": "The outcome of one record message, as spec/records.md, section 7, defines it.",
          "fields": [
            {
              "name": "id",
              "type": {
                "type": "string",
                "logicalType": "uuid"
              },
              "doc": "The id of the record, as the acknowledged message carried it in its record field."
            },
            {
              "name": "version",
              "type": "long",
              "doc": "The version of the acknowledged message."
            },
            {
              "name": "outcome",
              "type": {
                "type": "enum",
                "name": "AckOutcome",
                "doc": "What the receiver did with the message, as spec/records.md, section 7, defines. APPLIED: took the record or deleted it as the message says. MERGED: took it except fields its user had changed. KEPT: took nothing, because its user's change covers the whole record. DUPLICATE: already had this version. STALE: already had a higher version. WITHDRAWN: removed its copy of a record its sender no longer shares, for a WITHDRAW message, to come with axt-1026. The default is for schema resolution only; within one envelope format every symbol is known.",
                "symbols": [
                  "APPLIED",
                  "MERGED",
                  "KEPT",
                  "DUPLICATE",
                  "STALE",
                  "WITHDRAWN"
                ],
                "default": "DUPLICATE"
              },
              "doc": "What the receiver did with the message."
            },
            {
              "name": "receiver_version",
              "type": "long",
              "doc": "The receiver's version of the record after the message: equal to version, except for STALE, where it is higher."
            },
            {
              "name": "kept_fields",
              "type": {
                "type": "array",
                "items": "string"
              },
              "default": [],
              "doc": "For MERGED, the names of the fields whose values the receiver kept and that differ from the values in the message, as the writer schema of the message names them, each at most once. Empty for every other outcome."
            }
          ]
        }
      },
      "default": [],
      "doc": "The outcomes of record messages, 1 to 4096, each id and version at most once."
    }
  ]
}

{
  "type": "record",
  "name": "Error",
  "namespace": "axt",
  "doc": "The body of an ERROR message: a message the receiver could not process, and why. Defined in spec/protocol.md. Its schema changes only with a new envelope format.",
  "fields": [
    {
      "name": "to",
      "type": {
        "type": "fixed",
        "name": "ErrorTo",
        "size": 32,
        "doc": "An Ed25519 public key in the encoding of RFC 8032. Defined in spec/keys.md."
      },
      "doc": "The Ed25519 public key of the device that sent the reported message: in a live connection the key its HELLO proved, through a relay the key that signed the message. A device ignores an error that names another key."
    },
    {
      "name": "code",
      "type": {
        "type": "enum",
        "name": "ErrorCode",
        "doc": "Why the receiver could not process the message; spec/protocol.md defines each code. INVALID_MESSAGE: not a valid message of its kind. FORMAT_UNSUPPORTED: an envelope format the receiver does not read. TOO_LARGE: above a size limit of spec/envelope.md. SIGNATURE_INVALID: the signature does not verify. MANIFEST_INVALID: an invalid manifest. OFFER_INVALID: an invalid offer. RECORD_ID_INVALID: an invalid record id. VERSION_INVALID: a version below 1. SCHEMA_UNKNOWN: a body fingerprint the receiver has no schema for. NOT_ACCEPTED: a record message without an accepted offer of its type. TYPE_CHANGED: a record under another type than before. UNDECODABLE: a record body that cannot be decoded. DEVICE_REJECTED: a DEVICE_JOIN, DEVICE_ADD or DEVICE_REMOVE the receiver did not apply, as spec/keys.md, section 5, defines. VALUE_INVALID: a record that decodes but holds a value that breaks a rule of its type, named in field. RECORD_UNKNOWN: a CHANGE that does not hold the whole record, for a record the receiver does not have, to come with axt-1024. PROPOSALS_NOT_TAKEN: a PROPOSAL for a record whose sender takes none from the proposer, to come with axt-1027. The default is for schema resolution only; within one envelope format every symbol is known.",
        "symbols": [
          "INVALID_MESSAGE",
          "FORMAT_UNSUPPORTED",
          "TOO_LARGE",
          "SIGNATURE_INVALID",
          "MANIFEST_INVALID",
          "OFFER_INVALID",
          "RECORD_ID_INVALID",
          "VERSION_INVALID",
          "SCHEMA_UNKNOWN",
          "NOT_ACCEPTED",
          "TYPE_CHANGED",
          "UNDECODABLE",
          "DEVICE_REJECTED",
          "VALUE_INVALID",
          "RECORD_UNKNOWN",
          "PROPOSALS_NOT_TAKEN"
        ],
        "default": "INVALID_MESSAGE"
      },
      "doc": "Why the receiver could not process the message."
    },
    {
      "name": "message_hash",
      "type": {
        "type": "fixed",
        "name": "ErrorMessageHash",
        "size": 32,
        "doc": "A SHA-256 hash."
      },
      "doc": "The SHA-256 of the reported message as the receiver got it, from its single-object marker to its last byte; through a relay, after opening and removing the padding."
    },
    {
      "name": "record",
      "type": [
        "null",
        {
          "type": "record",
          "name": "ErrorRecord",
          "doc": "The record field of the reported message.",
          "fields": [
            {
              "name": "id",
              "type": "string",
              "doc": "The id as the reported message carried it, which may not be a valid UUID."
            },
            {
              "name": "version",
              "type": "long",
              "doc": "The version as the reported message carried it, which may be below 1."
            }
          ]
        }
      ],
      "default": null,
      "doc": "The record field of the reported message, when its signature verified, it carried one and its id is at most 64 bytes long. Null otherwise."
    },
    {
      "name": "fingerprint",
      "type": [
        "null",
        {
          "type": "fixed",
